describe('Username Pre-fill on Login', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should pre-fill username when user is logged in from previous session', () => {
    // Mock the localStorage to simulate a previous login
    cy.window().then((win) => {
      win.localStorage.setItem('authToken', 'mock-token');
      win.localStorage.setItem('username', 'john.doe');
    });

    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Attempt to login without entering username
    cy.get('[data-testid="email-input"]').type('jane.doe@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Wait for the login API call
    cy.wait('@loginRequest');

    // Verify the username is pre-filled
    cy.get('[data-testid="username-input"]').should('have.value', 'john.doe');

    // Verify the email is still empty
    cy.get('[data-testid="email-input"]').should('have.value', '');

    // Verify the login button is still visible
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify the success message appears
    cy.get('[data-testid="login-success-message"]').should('be.visible');
    cy.get('[data-testid="login-success-message"]').should('contain', 'Welcome back, john.doe');
  });

  it('should not pre-fill username when user is logged in from a different device', () => {
    // Mock the localStorage to simulate a previous login from a different device
    cy.window().then((win) => {
      win.localStorage.setItem('authToken', 'mock-token');
      win.localStorage.setItem('username', 'jane.doe');
    });

    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Attempt to login from a different device
    cy.get('[data-testid="email-input"]').type('jane.doe@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Wait for the login API call
    cy.wait('@loginRequest');

    // Verify the username is not pre-filled
    cy.get('[data-testid="username-input"]').should('have.value', '');

    // Verify the email is still empty
    cy.get('[data-testid="email-input"]').should('have.value', '');

    // Verify the login button is still visible
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify the success message appears
    cy.get('[data-testid="login-success-message"]').should('be.visible');
    cy.get('[data-testid="login-success-message"]').should('contain', 'Welcome back, jane.doe');
  });
});
